PUNCT = ["", "", "", "", ",", ".", ";", "!", "?"]

def english_text(n_sentences=400):
    out = []
    for _ in range(n_sentences):
        k = random.randint(6, 22)
        ws = []
        for i in range(k):
            w = random.choice(WORDS)
            if i == 0:
                w = w.capitalize()
            ws.append(w)
            p = random.choice(PUNCT)
            if p and i < k - 1:
                ws[-1] += p
        s = " ".join(ws) + "."
        out.append(s)
    return " ".join(out).encode()

def json_blob(n=120):
    recs = []
    for i in range(n):
        recs.append({
            "id": i,
            "name": random.choice(WORDS) + " " + random.choice(WORDS),
            "email": random.choice(WORDS) + str(random.randint(1,999)) + "@example.com",
            "active": random.choice([True, False]),
            "score": round(random.uniform(0, 100), 3),
            "tags": random.sample(WORDS, 3),
            "meta": {"created": "2023-%02d-%02d" % (random.randint(1,12), random.randint(1,28)),
                      "counts": [random.randint(0,1000) for _ in range(4)]},
            "description": " ".join(random.choice(WORDS) for _ in range(random.randint(5,15))),
        })
    return json.dumps(recs, indent=2).encode()

def corpus():
    a = english_text()
    b = json_blob()
    c = english_text(120)
    d = json_blob(40)
    return [a, b, c, d], ["eng", "json", "eng2", "json2"]

def score():
    import importlib, squeeze
    importlib.reload(squeeze)
    total_raw = total_comp = 0
    for data in corpus()[0]:
        try:
            comp = squeeze.compress(data)
            back = squeeze.decompress(comp)
        except Exception as e:
            print("EXC", e, file=sys.stderr); return 0.0
        if back != data:
            print("ROUNDTRIP FAIL", data[:20], file=sys.stderr); return 0.0
        total_raw += len(data); total_comp += len(comp)
    return total_raw / total_comp

if __name__ == "__main__":
    print(round(score(), 4))
